function useQualityOrbitTitle() {
    const ref = useRepeatingTitle(3300);
    useEffect(() => {
        const title = ref.current;
        if (!title) return;
        const letters = Array.from(title.querySelectorAll<HTMLElement>(".quality-orbit-letter"));
        const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
        let animation: gsap.core.Tween | undefined;
        const reset = () => {
            animation?.kill();
            gsap.set(letters, { clearProps: "transform,opacity" });
        };
        const play = () => {
            reset();
            if (motion.matches || !title.hasAttribute("data-title-revealing")) return;
            const bounds = title.getBoundingClientRect();
            const center = { x: bounds.width * .5, y: bounds.height * .5 };
            const radius = Math.min(bounds.width * .29, Math.max(42, bounds.height * .36));
            const orbitScale = bounds.width < 350 ? .55 : .35;
            const geometry = letters.map(letter => {
                const rect = letter.getBoundingClientRect();
                return { x: rect.left - bounds.left + rect.width / 2, y: rect.top - bounds.top + rect.height / 2 };
            });
            const setters = letters.map(letter => ({
                x: gsap.quickSetter(letter, "x", "px"), y: gsap.quickSetter(letter, "y", "px"),
                rotation: gsap.quickSetter(letter, "rotation", "deg"), scaleX: gsap.quickSetter(letter, "scaleX"), scaleY: gsap.quickSetter(letter, "scaleY"),
                opacity: gsap.quickSetter(letter, "opacity"),
            }));
            const clock = { time: 0 };
            const draw = () => setters.forEach((set, index) => {
                const launch = 1.05 + index * .037;
                const progress = Math.max(0, Math.min(1, (clock.time - launch) / .8));
                const orbitTime = Math.min(clock.time, launch);
                const angle = index / letters.length * Math.PI * 2 - Math.PI / 2 + orbitTime / 1.05 * Math.PI * 2;
                const start = { x: center.x + Math.cos(angle) * radius, y: center.y + Math.sin(angle) * radius };
                const target = geometry[index];
                // Leave the circle along its tangent, then arc into the original text slot.
                const control = { x: start.x - Math.sin(angle) * radius * .65, y: start.y + Math.cos(angle) * radius * .65 };
                const t = 1 - Math.pow(1 - progress, 3), inverse = 1 - t;
                const x = inverse * inverse * start.x + 2 * inverse * t * control.x + t * t * target.x;
                const y = inverse * inverse * start.y + 2 * inverse * t * control.y + t * t * target.y;
                set.x(x - target.x); set.y(y - target.y);
                set.rotation((Math.sin(angle) * 18) * inverse);
                set.scaleX(orbitScale + (1 - orbitScale) * t); set.scaleY(orbitScale + (1 - orbitScale) * t);
                set.opacity(Math.min(1, clock.time / .18));
            });
            draw();
            animation = gsap.to(clock, { time: 3.1, duration: 3.1, ease: "none", onUpdate: draw,
                onComplete: () => gsap.set(letters, { clearProps: "transform,opacity" }),
            });
        };
        const observer = new MutationObserver(play);
        observer.observe(title, { attributes: true, attributeFilter: ["data-title-revealing"] });
        let size = `${title.offsetWidth}:${title.offsetHeight}`;
        const resize = new ResizeObserver(() => {
            const next = `${title.offsetWidth}:${title.offsetHeight}`;
            if (next !== size) { size = next; play(); }
        });
        resize.observe(title);
        motion.addEventListener("change", reset);
        play();
        return () => { observer.disconnect(); resize.disconnect(); motion.removeEventListener("change", reset); reset(); };
    }, [ref]);
    return ref;
}

