function twqualityPage(value: string | undefined): string { const names = (value ?? "").split(/\s+/).filter(Boolean); const selected = new Map<string, string>(); for (const name of names) for (const token of (twqualityPageRules[name] ?? "").split(" ").filter(Boolean)) { const matches = [...token.matchAll(/\[([\w-]+):/g)]; const match = matches[matches.length - 1]; const key = match ? token.slice(0, match.index) + "|" + match[1] : token.replace(/animate-[\w-]+!?$/, "animation"); const old = selected.get(key); if (!old || (twqualityPagePriority[token] ?? 0) >= (twqualityPagePriority[old] ?? 0)) selected.set(key, token); } return [...names, ...selected.values()].join(" "); }
